css:
.ma-sim-container {
    padding: 28px 32px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

.ma-sim-container .ma-sim-header {
    background: #1a2744;
    color: #f4f5f7;
    padding: 24px 28px;
    border-radius: 4px;
    margin-bottom: 20px;
    border-left: 6px solid #c9a227;
}
.ma-sim-container .ma-sim-header h1 {
    font-size: 1.55rem;
    margin: 6px 0 4px 0;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: #f4f5f7;
}
.ma-sim-container .ma-sim-header-meta {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: #c9a227;
    font-weight: 700;
}
.ma-sim-container .ma-sim-header-sub {
    font-size: 0.92rem;
    color: #c0c8d6;
    margin-top: 6px;
}

.ma-sim-container .ma-sim-period-strip {
    background: #ffffff;
    border: 1px solid #d6dae3;
    border-radius: 4px;
    padding: 12px 18px;
    margin-bottom: 18px;
    font-size: 0.92rem;
    font-weight: 600;
    color: #1a2744;
    display: flex;
    align-items: center;
    gap: 8px;
}
.ma-sim-container .ma-sim-period-tag {
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-size: 0.72rem;
    color: #5c6479;
}
.ma-sim-container .ma-sim-period-strip-divider {
    color: #63697a;
    margin: 0 6px;
}

.ma-sim-container .ma-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 20px;
}
.ma-sim-container .ma-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d6dae3;
    border-radius: 4px;
    padding: 16px 18px;
    border-top: 3px solid #1a2744;
    transition: box-shadow 0.2s ease;
}
.ma-sim-container .ma-sim-kpi-card:hover {
    box-shadow: 0 2px 8px rgba(26,39,68,0.08);
}
.ma-sim-container .ma-sim-kpi-card-r1 { border-top-color: #2a6ab8; }
.ma-sim-container .ma-sim-kpi-card-r2 { border-top-color: #4f7a4a; }
.ma-sim-container .ma-sim-kpi-card-r3 { border-top-color: #c9a227; }
.ma-sim-container .ma-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #5c6479;
    font-weight: 700;
    margin-bottom: 8px;
}
.ma-sim-container .ma-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
    font-variant-numeric: tabular-nums;
}

.ma-sim-container .ma-sim-briefing {
    background: #ffffff;
    border: 1px solid #d6dae3;
    border-left: 4px solid #c9a227;
    border-radius: 4px;
    padding: 16px 20px;
    margin-bottom: 20px;
}
.ma-sim-container .ma-sim-briefing-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #5c6479;
    font-weight: 700;
    margin-bottom: 6px;
}
.ma-sim-container .ma-sim-briefing-text {
    font-size: 0.95rem;
    color: #1a2744;
    line-height: 1.5;
}

.ma-sim-container .ma-sim-controls {
    background: #ffffff;
    border: 1px solid #d6dae3;
    border-radius: 4px;
    padding: 24px 26px;
    margin-bottom: 18px;
}
.ma-sim-container .ma-sim-controls h3 {
    font-size: 1.05rem;
    font-weight: 700;
    color: #1a2744;
    border-bottom: 2px solid #c9a227;
    padding-bottom: 10px;
    margin-bottom: 18px;
}
.ma-sim-container .ma-sim-decision-row {
    margin-bottom: 16px;
}
.ma-sim-container .ma-sim-decision-row label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
}
.ma-sim-container .ma-sim-controls select,
.ma-sim-container .ma-sim-controls input {
    background: #ffffff;
    border: 1px solid #c0c6d4;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.ma-sim-container .ma-sim-controls select:focus,
.ma-sim-container .ma-sim-controls input:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.12);
}
.ma-sim-container .ma-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}

.ma-sim-container .ma-sim-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-bottom: 20px;
}
.ma-sim-container .ma-sim-actions .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    padding: 10px 28px;
    font-weight: 600;
    letter-spacing: 0.02em;
    border-radius: 3px;
    color: #f4f5f7;
}
.ma-sim-container .ma-sim-actions .btn-primary:hover {
    background: #243454;
    border-color: #243454;
    color: #ffffff;
}
.ma-sim-container .ma-sim-actions .btn-outline-secondary {
    color: #5c6479;
    border-color: #c0c6d4;
    background: #ffffff;
    border-radius: 3px;
}
.ma-sim-container .ma-sim-actions .btn-outline-secondary:hover {
    background: #eef0f4;
    color: #1a2744;
}

.ma-sim-container .ma-sim-history {
    background: #ffffff;
    border: 1px solid #d6dae3;
    border-radius: 4px;
    padding: 18px 22px;
    margin-bottom: 18px;
}
.ma-sim-container .ma-sim-history h3 {
    font-size: 0.85rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 12px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.ma-sim-container .ma-sim-history table {
    font-size: 0.86rem;
    color: #1a2744;
    width: 100%;
}
.ma-sim-container .ma-sim-history table thead th {
    background: #1a2744;
    color: #f4f5f7;
    font-weight: 600;
    border: none;
    padding: 10px 12px;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.ma-sim-container .ma-sim-history table tbody td {
    padding: 9px 12px;
    border-bottom: 1px solid #e5e7ed;
    vertical-align: top;
}
.ma-sim-container .ma-sim-history table tbody tr:nth-child(even) td {
    background: #f9fafc;
}

.ma-sim-container .ma-sim-chart-wrap {
    background: #ffffff;
    border: 1px solid #d6dae3;
    border-radius: 4px;
    padding: 18px 22px;
    height: 320px;
    position: relative;
}

@media (max-width: 768px) {
    .ma-sim-container {
        padding: 16px;
    }
    .ma-sim-container .ma-sim-header h1 {
        font-size: 1.2rem;
    }
    .ma-sim-container .ma-sim-kpi-grid {
        grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    }
    .ma-sim-container .ma-sim-kpi-value {
        font-size: 1.3rem;
    }
    .ma-sim-container .ma-sim-controls {
        padding: 18px 18px;
    }
    .ma-sim-container .ma-sim-chart-wrap {
        height: 260px;
    }
}

/* --- EQIL additions (adapter 1.1.0) --- */
.ma-sim-container .ma-sim-analysis {
    background: #ffffff;
    border: 1px solid #d9dde4;
    border-left: 4px solid #1a2744;
    border-radius: 4px;
    padding: 16px 20px;
    margin-bottom: 18px;
}
.ma-sim-container .ma-sim-analysis-label {
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #5c6479;
    font-weight: 600;
    margin-bottom: 6px;
}
.ma-sim-container .ma-sim-analysis-body {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #1a2744;
}
.ma-sim-container .ma-sim-complete-banner {
    margin: 12px 0;
    padding: 12px 16px;
    border-radius: 4px;
    border: 1px solid #1a2744;
    background: #eef1f6;
    color: #1a2744;
    font-weight: 600;
}
.ma-sim-container button:focus-visible,
.ma-sim-container select:focus-visible,
.ma-sim-container input:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .ma-sim-container * {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

