                const pm = document.getElementById('priceMethodSelect');
                if (pm) decisions.priceMethod = pm.value;
                const rw = document.getElementById('rwStructureSelect');
                if (rw) decisions.rwStructure = rw.value;
                const id = document.getElementById('indemnificationSelect');
                if (id) decisions.indemnification = id.value;
                const mac = document.getElementById('macLanguageSelect');
                if (mac) decisions.macLanguage = mac.value;
                const tf = document.getElementById('terminationFeeSelect');
                if (tf) decisions.terminationFee = tf.value;
            } else if (period === 2) {
                const cf = document.getElementById('cfiusPostureSelect');
                if (cf) decisions.cfiusPosture = cf.value;
                const eu = document.getElementById('euPostureSelect');
                if (eu) decisions.euPosture = eu.value;
            } else if (period === 3) {
                const md = document.getElementById('multipleDefenseSelect');
                if (md) decisions.multipleDefense = md.value;
                const cs = document.getElementById('cfiusScopeSelect');
                if (cs) decisions.cfiusScope = cs.value;
                const ia = document.getElementById('integrationApproachSelect');
                if (ia) decisions.integrationApproach = ia.value;
            }
            return true;
        }

        calculateResults(state) {
            const r = this._computeRound(state);
            return {
                period: r.period,
                roundName: r.roundName,
                roundScore: r.roundScore,
                dealScore: r.dealScore,
                chairConfidence: r.chairConfidence,
                feedback: r.feedback,
                composite: r.composite,
                overallScore: r.composite,
                totalScore: r.composite,
                score: r.composite
            };
        }

        _computeRound(state) {
            const d = state.decisions;
            const period = state.currentPeriod;
            let roundScore = 0;
            let feedback = '';
            let roundName = '';

            if (period === 1) {
                roundScore = this._scoreSPA(d);
                state.domainState.spaQuality = roundScore;
                feedback = this._spaFeedback(d);
                roundName = window.mySimulation.t('round_name_r1');
            } else if (period === 2) {
                roundScore = this._scoreRegulatory(d);
                state.domainState.regulatoryQuality = roundScore;
                feedback = this._regulatoryFeedback(d);
                roundName = window.mySimulation.t('round_name_r2');
                state.domainState.regulatoryRisk = Math.max(5, 100 - roundScore);
            } else if (period === 3) {
                roundScore = this._scoreDefense(d);
                state.domainState.defenseQuality = roundScore;
                feedback = this._defenseFeedback(d);
                roundName = window.mySimulation.t('round_name_r3');
            }

            const completed = [
                state.domainState.spaQuality,
                state.domainState.regulatoryQuality,
                state.domainState.defenseQuality
            ].filter((x) => x > 0);
            state.domainState.dealScore = completed.length
                ? Math.round(completed.reduce((s, v) => s + v, 0) / completed.length)
                : 0;

            const chairDelta = (roundScore - 50) * 1.0;
            state.domainState.chairConfidence = Math.min(100, Math.max(5,
                state.domainState.chairConfidence + chairDelta));

            if (!Array.isArray(state.domainState.scoreHistory)) state.domainState.scoreHistory = [];
            if (!Array.isArray(state.domainState.roundLabels)) state.domainState.roundLabels = [];
            state.domainState.scoreHistory.push(roundScore);
            state.domainState.roundLabels.push('R' + period);

            const composite = this._composite(state.domainState, d);
            state.domainState.composite = composite;
            state.domainState.overallScore = composite;
            state.domainState.performanceBand = this._band(composite);
            // platform score: the deal composite (0 to 100), the same value getPerformanceSummary reports as overallScore
            var prevPerf = state.domainState.performance;
            state.domainState.performance = Object.assign({}, (prevPerf && typeof prevPerf === 'object') ? prevPerf : {}, { overallScore: Math.max(0, Math.min(100, Math.round(composite))) });
            state.domainState.lastAnalysis = feedback;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._renderAnalysis(feedback);
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                roundName: roundName,
                roundScore: roundScore,
                dealScore: state.domainState.dealScore,
                chairConfidence: Math.round(state.domainState.chairConfidence),
                feedback: feedback,
                composite: composite
            };
        }

        _scoreSPA(d) {
            let s = 0;
            if (d.priceMethod === 'locked-box') s += 22;
            else if (d.priceMethod === 'ccaw') s += 13;
            else s += 9;

            if (d.rwStructure === 'rwi') s += 22;
            else if (d.rwStructure === 'escrow') s += 13;
            else s += 16;

            if (d.indemnification === 'tiered') s += 18;
            else if (d.indemnification === 'standard') s += 11;
            else s += 6;

            if (d.macLanguage === 'durational') s += 20;
            else if (d.macLanguage === 'narrow') s += 14;
            else s += 8;

            if (d.terminationFee === 'rbe-burdensome') s += 18;
            else if (d.terminationFee === 'hohw') s += 11;
            else s += 6;

            return Math.min(100, s);
        }

        _scoreRegulatory(d) {
            let s = 0;
            if (d.cfiusPosture === 'declaration') s += 50;
            else if (d.cfiusPosture === 'full-notice') s += 36;
            else s += 8;

            if (d.euPosture === 'national-only') s += 48;
            else if (d.euPosture === 'simplified-fallback') s += 38;
            else if (d.euPosture === 'long-form') s += 26;
            else s += 6;

            return Math.min(100, s);
        }

        _scoreDefense(d) {
            let s = 0;
            if (d.multipleDefense === 'three-leg') s += 38;
            else if (d.multipleDefense === 'mcallen-only') s += 22;
            else s += 10;

            if (d.cfiusScope === 'asset-specific') s += 28;
            else s += 8;

            if (d.integrationApproach === 'sister-sub') s += 34;
            else if (d.integrationApproach === 'merge-in') s += 10;
            else s += 16;

            return Math.min(100, s);
        }

