            const parts = [];
            if (d.priceMethod === 'locked-box') parts.push(window.mySimulation.t('fb_price_lockedbox'));
            else if (d.priceMethod === 'ccaw') parts.push(window.mySimulation.t('fb_price_ccaw'));
            else parts.push(window.mySimulation.t('fb_price_lockedno'));

            if (d.rwStructure === 'rwi') parts.push(window.mySimulation.t('fb_rw_rwi'));
            else if (d.rwStructure === 'escrow') parts.push(window.mySimulation.t('fb_rw_escrow'));
            else parts.push(window.mySimulation.t('fb_rw_hybrid'));

            if (d.macLanguage === 'durational') parts.push(window.mySimulation.t('fb_mac_duration'));
            else if (d.macLanguage === 'narrow') parts.push(window.mySimulation.t('fb_mac_narrow'));
            else parts.push(window.mySimulation.t('fb_mac_broad'));

            if (d.terminationFee === 'rbe-burdensome') parts.push(window.mySimulation.t('fb_tf_rbe'));
            else if (d.terminationFee === 'hohw') parts.push(window.mySimulation.t('fb_tf_hohw'));
            else parts.push(window.mySimulation.t('fb_tf_best'));

            return parts.join(' · ');
        }

