        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            const ds = (window.mySimulation && window.mySimulation.state)
                ? (window.mySimulation.state.domainState || {}) : {};
            const dec = (window.mySimulation && window.mySimulation.state)
                ? (window.mySimulation.state.decisions || {}) : {};
            const scores = history.map((r) => (r.results && r.results.roundScore) || 0);
            const roundTotal = scores.reduce((s, p) => s + p, 0);
            const avg = scores.length ? roundTotal / scores.length : 0;
            const composite = this._composite(ds, dec);
            const band = this._band(composite);

            const labelKey = {
                excellent: 'perf_excellent',
                good: 'perf_good',
                developing: 'perf_developing',
                needs_work: 'perf_beginner'
            }[band];

            const insights = [];
            if (dec.cfiusPosture === 'no-file') {
                insights.push(this._t('insight_cfius_nofile'));
            }
            if (dec.euPosture === 'no-file') {
                insights.push(this._t('insight_eu_nofile'));
            }
            if (composite > 80) insights.push(this._t('insight_signs'));
            else if (composite > 60) insights.push(this._t('insight_partial'));
            else insights.push(this._t('insight_walk'));

            return {
                spaQuality: Number(ds.spaQuality) || 0,
                regulatoryQuality: Number(ds.regulatoryQuality) || 0,
                defenseQuality: Number(ds.defenseQuality) || 0,
                roundScoreTotal: Math.round(roundTotal),
                avgScore: Math.round(avg),
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                chairConfidence: Math.round(Number(ds.chairConfidence) || 0),
                regulatoryRisk: Math.round(Number(ds.regulatoryRisk) || 0),
                performance: this._t(labelKey),
                performanceKey: band,
                performanceLabel: this._t(labelKey),
                insights: insights
            };
        }

