                next: this._L('What to take away', 'Qué llevarte')
            };
            const rows = ''
                + '<li><strong>' + lbl.score + ':</strong> ' + score + '/100 (' + (s.performanceLabel || s.performance || '') + ')</li>'
                + '<li><strong>' + lbl.spa + ':</strong> ' + (s.spaQuality != null ? s.spaQuality : '-') + '/100</li>'
